mapper.select:
SELECT  FROM videos
WHERE create_time < #{before}
ORDER BY create_time DESC LIMIT #{limit}

SELECT  FROM videos

    WHERE likes_count < #{likesBefore} OR (likes_count = #{likesBefore} AND id < #{idBefore})

ORDER BY likes_count DESC, id DESC LIMIT #{limit}

SELECT  FROM videos
WHERE author_id IN (SELECT vlogger_id FROM socials WHERE follower_id = #{accountId})
AND create_time < #{before}
ORDER BY create_time DESC LIMIT #{limit}

SELECT  FROM videos

    WHERE popularity < #{popularityBefore}
       OR (popularity = #{popularityBefore} AND create_time < #{timeBefore})
       OR (popularity = #{popularityBefore} AND create_time = #{timeBefore} AND id < #{idBefore})

ORDER BY popularity DESC, create_time DESC, id DESC LIMIT #{limit}
